-- Singapore deep-dive content: page, stats, file_format cards,
-- scope_transmission cards + lifecycle card ("The exchange flow"),
-- steps, penalties_related cards, portal. No penalty rows/table.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Peppol, transitioning 4-corner → 5-corner', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. PINT-SG technical detail, phased rollout dates, and IRAS reporting requirements continue to evolve — confirm current requirements directly with IRAS or IMDA before building an integration.', 'Singapore is running one of the longest, most granular phase-in schedules in this tracker — six years, sliced by both incorporation status and revenue band.', 'SG Peppol BIS Billing 3.0 is a genuine national extension of the European standard — not a from-scratch local format.', 'InvoiceNow is deliberately transitioning from a pure exchange network into a tax-reporting one — the "5-corner" upgrade adds IRAS as a genuine participant, not just an observer.', 'Registration hinges on getting a Peppol ID before you ever touch IRAS — treat it as the true first step, not a formality.', 'Singapore''s approach is notably gradual and consultative — a genuinely different posture from the faster-moving mandates elsewhere in this tracker.' FROM countries WHERE name_en = 'Singapore';

