INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Format', '[["Current standard", "SG Peppol BIS Billing 3.0"], ["Base", "European Peppol BIS 3.0, extended for Singapore-specific requirements"], ["Digital signature", "Not required from the taxpayer"]]', 'Unlike clearance-model countries, InvoiceNow doesn''t require the taxpayer to digitally sign invoices — security, integrity, and authenticity are safeguarded by the Peppol network and accredited Access Point providers instead.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Mandatory Data Elements', '[["Party identifiers", "Supplier/customer UEN and GST registration numbers (GSTN)"], ["Tax codes", "Mapped to IRAS-approved GST category codes (Annex E, e-Tax Guide)"], ["Aggregated entries", "Special \"POS\" or \"PCP\" indicators for point-of-sale/petty-cash purchases"]]', 'Mapping your internal tax codes correctly to IRAS''s standardised GST category list is one of the highest-friction technical steps — get this wrong and your submissions will be flagged.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Identifiers', '[["Peppol ID base", "Unique Entity Number (UEN)"], ["Also underlies", "PayNow Corporate (Singapore''s e-payment scheme)"], ["Multi-entity businesses", "Each GST-registered entity needs its own Peppol ID"]]', 'For groups with multiple operating entities, design for a separate Peppol ID and Access Point configuration per entity from the start — retrofitting this after go-live is genuinely disruptive.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Evolving format: PINT SG', '[["Fields not in older templates", "Supply type codes, line-level GST amounts, UEN-linked Peppol IDs"]]', 'If your invoice templates were built before InvoiceNow''s GST requirement, expect meaningful gaps against the newer PINT-SG-aligned field requirements — audit rather than assume compatibility.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Governance', '[["IMDA", "Singapore''s Peppol Authority; defines Peppol Authority Specific Requirements (PASR)"], ["IRAS", "Receives the reported invoice data for GST administration"]]', 'IMDA accredits the Access Point/SMP service providers; IRAS is the tax authority consuming the data those providers transmit — two distinct roles worth keeping separate in your mental model.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Submission timing', '[["Deadline", "Earlier of the GST return filing date or the statutory deadline for that return"]]', 'This ties your InvoiceNow transmission cadence directly to your existing GST filing calendar rather than requiring a separate real-time deadline to track.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Roles: IRSP vs. AP', '[["IRSP", "InvoiceNow-Ready Solution Provider — provides the accounting software"], ["AP", "Access Point — enables network connectivity"]]', 'These are often the same commercial provider in practice, but they''re conceptually distinct roles — worth clarifying with your vendor which function they''re actually performing for you.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

