INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Obtain your Peppol ID', 'Work with your chosen IRSP or AP provider to register in the SG Peppol Directory using your UEN — this is a prerequisite for any InvoiceNow transmission, separate from your ACRA registration or GST registration number itself.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Singapore' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Singapore';
