INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🐢 A deliberately long runway', NULL, NULL, 'Six years between the first mandatory cohort (Nov 2025) and full rollout (Apr 2031) is among the longest phase-in periods in this tracker — Singapore appears to be prioritising smooth adoption over speed.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🔄 4-corner to 5-corner is a genuine architecture shift', NULL, NULL, 'The addition of IRAS as a "5th corner" wasn''t in InvoiceNow''s original 2019 design — it represents Singapore evolving a voluntary exchange network into a tax-reporting one over time, rather than building a clearance system from scratch.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '💰 Transitional support available', NULL, NULL, 'Government grants have historically supported InvoiceNow adoption costs — worth checking current IMDA/IRAS schemes if cost is a barrier to early adoption.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
