INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🌏 Regional Peppol leadership', NULL, NULL, 'As the first Peppol Authority outside Europe, Singapore''s InvoiceNow experience has directly informed how newer Asia-Pacific Peppol markets like Malaysia and Japan have approached their own rollouts.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Singapore' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

